#include <stdio.h>

double legendre(int n, double x) {
    if (n == 0) return 1;
    if (n == 1) return x;
    return ((2*n - 1)*x*legendre(n-1, x) - (n-1)*legendre(n-2, x)) / n;
}

int main(void) {
    int n;
    double x;
    scanf("%d%lf", &n, &x);
    printf("%.6f\n", legendre(n, x));
    return 0;
}
